 effect)\nend\n\nreturn itemObject\n"},["scripts/items/lucid_elixir_i.lua"]={["Path"]="scripts/items/lucid_elixir_i.lua",["SHA256"]="d400fe3e95a8d6e750f57f838b15a6f4ccb7d81beb5729ad830fb1cb4c65e9ab",["Text"]="-----------------------------------\n-- ID: 5830\n-- Item: Lucid Elixir I\n-- Item Effect: Restores 50% of HP and MP\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if\n        target:getMaxHP() == target:getHP() and\n        target:getMaxMP() == target:getMP()\n    then\n        return xi.msg.basic.ITEM_UNABLE_TO_USE_2\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target)\n    target:addHP(target:getMaxHP() * 0.5 * xi.settings.main.ITEM_POWER)\n    target:addMP(target:getMaxMP() * 0.5 * xi.settings.main.ITEM_POWER)\n    target:messageBasic(xi.msg.basic.RECOVERS_HP_AND_MP)\nend\n\nreturn itemObject\n"},["scripts/items/lucid_elixir_ii.lua"]={["Path"]="scripts/items/lucid_elixir_ii.lua",["SHA256"]="52a9eae2f119cac7aa9e82bfd6ef224a74fb7e894dc0aa508fd1bf39f5dd11f5",["Text"]="-----------------------------------\n-- ID: 5831\n-- Item: Lucid Elixir II\n-- Item Effect: Restores 75% of HP and MP\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if\n        target:getMaxHP() == target:getHP() and\n        target:getMaxMP() == target:getMP()\n    then\n        return xi.msg.basic.ITEM_UNABLE_TO_USE_2\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target)\n    target:addHP(target:getMaxHP() * 0.75 * xi.settings.main.ITEM_POWER)\n    target:addMP(target:getMaxMP() * 0.75 * xi.settings.main.ITEM_POWER)\n    target:messageBasic(xi.msg.basic.RECOVERS_HP_AND_MP)\nend\n\nreturn itemObject\n"},["scripts/items/lucid_ether_i.lua"]={["Path"]="scripts/items/lucid_ether_i.lua",["SHA256"]="f5c17c817debf755832cbcf983543d38c1bb211a507d847a5ce784306f29bad7",["Text"]="------