  target:messageBasic(xi.msg.basic.RECOVERS_HP, 0, target:addHP(2000 * xi.settings.main.ITEM_POWER))\nend\n\nreturn itemObject\n"},["scripts/items/lucky_egg.lua"]={["Path"]="scripts/items/lucky_egg.lua",["SHA256"]="b3ffdd1e459a4a9efc6bd65a4401042371250b3cc50d8f00ef04a5be36c67591",["Text"]="-----------------------------------\n-- ID: 4600\n-- Item: lucky_egg\n-- Food Effect: 60Min, All Races\n-----------------------------------\n-- Health 14\n-- Magic 14\n-- Evasion 10\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 3600, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_HP, 14)\n    effect:addMod(xi.mod.FOOD_MP, 14)\n    effect:addMod(xi.mod.EVA, 10)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/lugworm_belt.lua"]={["Path"]="scripts/items/lugworm_belt.lua",["SHA256"]="7a244ee470d5c655ff85bc7294ba6a09b508a5d6b0900784ae4f399d966e2bc1",["Text"]="-----------------------------------\n-- ID: 15453\n-- lugworm_belt\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.LUGWORM, 12 } })\nend\n\nreturn itemObject\n"},["scripts/items/luminohelix_schema.lua"]={["Path"]="scripts/items/luminohelix_schema.lua",["SHA256"]="d6b7b0163496657fa4ce255d25496a414fe0624198421f78ea460090f9032e24",["Text"]="-----------------------------------\n-- ID: 6047\n-- Luminohelix Schema\n-- Teaches the black magic Luminohelix\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return target:canLearnSpell(xi.magic.spell.LUMINOHELIX)\nend\n\nitemObject.onItemUse = function(target)\n    target:addSpell(xi.magic.spell.LUMINOHELIX)\nend\n\nreturn itemObject\n"},["scripts/items/lungfish.lua"]={["Path"]="scripts/items/lungfish.lua",["SHA256"]="d164868d5fabf2c802b1bce20b04ee2c5095e35c95fe6b2c5cf2ad8c14fd6c46",["Text"]="-----------------------------------\n-- ID: 4315\n-- Item: Lungfish\n-- Food Effect: 5Min, Mithra only\n-----------------------------------\n-- Dexterity -2\n-- Mind 4\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.RAW_FISH)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 300, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.DEX, -2)\n    effect:addMod(xi.mod.MND, 4)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/lungo-nangos_thesis.lua"]={["Path"]="scripts/items/lungo-nangos_thesis.lua",["SHA256"]="19c4415d0ec1b198bc0aa6dfa168273facddad974a8dad10aff7f15c9603ab7b",["Text"]="-----------------------------------\n-- ID: 6703\n-- Item: Lungo-Nango's Thesis\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    -- Only usable on a mastered job.\n    if not target:hasKeyItem(xi.keyItem.MASTER_BREAKER) then\n        return xi.msg.basic.ITEM_UNABLE_TO_USE\n    end\n\n    if target:getMod(xi.mod.SUPERIOR_LEVEL) ~= 5 then\n        return xi.msg.basic.ITEM_UNABLE_TO_USE\n    end\n\n    -- Item disabled until Examplar Points support is added\n    return xi.msg.basic.ITEM_UNABLE_TO_USE\nend\n\nitemObject.onItemUse = function(target)\n    -- TODO: Grant 4000~6000 examplar points to current job\nend\n\nreturn itemObject\n"},["scripts/items/m&p_cracker.lua"]={["Path"]="scripts/items/m&p_cracker.lua",["SHA256"]="d347c3eaa15e233143b28a26e3e9f2ec0197f207618936f66d063ae2f3ff1639",["Text"]="-----------------------------------\n-- ID: 5640\n-- Item: M&P Cracker\n-- Food Effect: 3Min, All Races\n-----------------------------------\n-- Vitality 5\n-- Mind -5\n-- Defense % 25\n-- Attack Cap 154\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 180, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.VIT, 5)\n    effect:addMod(xi.mod.MND, -5)\n    effect:addMod(xi.mod.FOOD_DEFP, 25)\n    effect:addMod(xi.mod.FOOD_DEF_CAP, 154)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/m&p_doner_kebab.lua"]={["Path"]="scripts/items/m&p_doner_kebab.lua",["SHA256"]="fdbce8b77b26e54598cac1018fbfdd989f6c26e13e8b86c9916ee9ec85e9d124",["Text"]="-----------------------------------\n-- ID: 5717\n-- Item: M&P Doner Kabob\n-- Food Effect: 5Min, All Races\n-----------------------------------\n-- HP 5% (cap 150)\n-- MP 5% (cap 150)\n-- hHP +2\n-- hMP +2\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 300, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_HPP, 5)\n    effect:addMod(xi.mod.FOOD_HP_CAP, 150)\n    effect:addMod(xi.mod.FOOD_MPP, 5)\n    effect:addMod(xi.mod.FOOD_MP_CAP, 150)\n    effect:addMod(xi.mod.HPHEAL, 2)\n    effect:addMod(xi.mod.MPHEAL, 2)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/m&p_dumpling.lua"]={["Path"]="scripts/items/m&p_dumpling.lua",["SHA256"]="784f5c848734b5360474bd48f739adf14c2a127a5782412e38b2377cc203f756",["Text"]="-----------------------------------\n-- ID: 5641\n-- Item: M&P Dumpling\n-- Food Effect: 3Min, All Races\n-----------------------------------\n-- Intelligence 5\n-- Agility -5\n-- MP 30\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 180, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.FOOD_MP, 30)\n    effect:addMod(xi.mod.INT, 5)\n    effect:addMod(xi.mod.AGI, -5)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/maats_cap.lua"]={["Path"]="scripts/items/maats_cap.lua",["SHA256"]="889a39e23feb422d4ebe214420118c71f49fe7da6c31b05820fd8db2bf80ad5f",["Text"]="-----------------------------------\n-- ID: 15194\n-- Item: Maats Cap\n-- Teleports to Ru'Lude gardens\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    target:addStatusEffect(xi.effect.TELEPORT, { power = xi.teleport.id.MAAT, duration = 4, origin = user, icon = 0 })\nend\n\nreturn itemObject\n"},["scripts/items/magic_slacks.lua"]={["Path"]="scripts/items/magic_slacks.lua",["SHA256"]="def955812e79ce75175fdc568f4790527c68940827ccb5fde93c273e23b581ac",["Text"]="-----------------------------------\n-- ID: 15372\n-- Item: Magic Slacks\n-- Item Effect: Restores 30-39 MP\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if target:getMP() == target:getMaxMP() then\n        return xi.msg.basic.ITEM_UNABLE_TO_USE\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target)\n    local mpHeal = math.randomInt(30, 40)\n    local dif = target:getMaxMP() - target:getMP()\n    if mpHeal > dif then\n        mpHeal = dif\n    end\n\n    target:addMP(mpHeal)\n    target:messageBasic(xi.msg.basic.RECOVERS_MP, 0, mpHeal)\nend\n\nreturn itemObject\n"},["scripts/items/magma_steak.lua"]={["Path"]="scripts/items/magma_steak.lua",["SHA256"]="ed2fed3d8bd972bffb87852169711dee398931ef11715f0c3ba5d369a5f57e0f",["Text"]="-----------------------------------\n-- ID: 6071\n-- Item: Magma Steak\n-- Food Effect: 180 Min, All Races\n-----------------------------------\n-- Strength +8\n-- Attack +23% Cap 180\n-- Ranged Attack +23% Cap 180\n-- Vermin Killer +5\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 10800, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.STR, 8)\n    effect:addMod(xi.mod.FOOD_ATTP, 23)\n    effect:addMod(xi.mod.FOOD_ATT_CAP, 180)\n    effect:addMod(xi.mod.FOOD_RATTP, 23)\n    effect:addMod(xi.mod.FOOD_RATT_CAP, 180)\n    effect:addMod(xi.mod.VERMIN_KILLER, 5)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/magma_steak_+1.lua"]={["Path"]="scripts/items/magma_steak_+1.lua",["SHA256"]="ba17cc05a120a1d5c7167088bc200d992d87a23151f286bcd5e101c2f68b7b8a",["Text"]="-----------------------------------\n-- ID: 6072\n-- Item: Magma Steak +1\n-- Food Effect: 240 Min, All Races\n-----------------------------------\n-- Strength +9\n-- Attack +24% Cap 185\n-- Ranged Attack +24% Cap 185\n-- Vermin Killer +6\n-----------------------------------\n---@type TItemFood\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.foodOnItemCheck(target, xi.foodType.BASIC)\nend\n\nitemObject.onItemUse = function(target, user, item, action)\n    target:addStatusEffect(xi.effect.FOOD, { duration = 14400, origin = user, sourceType = xi.effectSourceType.FOOD, sourceTypeParam = item:getID() })\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.STR, 9)\n    effect:addMod(xi.mod.FOOD_ATTP, 24)\n    effect:addMod(xi.mod.FOOD_ATT_CAP, 185)\n    effect:addMod(xi.mod.FOOD_RATTP, 24)\n    effect:addMod(xi.mod.FOOD_RATT_CAP, 185)\n    effect:addMod(xi.mod.VERMIN_KILLER, 6)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/magna_gilet_+1.lua"]={["Path"]="scripts/items/magna_gilet_+1.lua",["SHA256"]="87f7efbac39d5cd5a6cf32fc43c7e319233846272b6312969d295531632a00f7",["Text"]="-----------------------------------\n-- ID: 11275\n-- Item: magna gilet +1\n-- Teleport's user to Purgonorgo Isle\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    local result = 0\n    if not target:hasVisitedZone(xi.zone.BIBIKI_BAY) then\n        result = xi.msg.basic.ITEM_UNABLE_TO_USE_2\n    end\n\n    return result\nend\n\nitemObject.onItemUse = function(target, user)\n    target:addStatusEffect(xi.effect.TELEPORT, { power = xi.teleport.id.PURGONORGO, duration = 3, origin = user, icon = 0 })\nend\n\nreturn itemObject\n"},["scripts/items/magna_top_+1.lua"]={["Path"]="scripts/items/magna_top_+1.lua",["SHA256"]="0f875e5d1cb29855b7e76c20ff50483aff0b385b99bbae880b9a748cd05f43c7",["Text"]="-----------------------------------\n-- ID: 11276\n-- Item: magna top +1\n-- Teleport's user to Purgonorgo Isle\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    local result = 0\n    if not target:hasVisitedZone(xi.zone.BIBIKI_BAY) then\n        result = xi.msg.basic.ITEM_UNABLE_TO_USE_2\n    end\n\n    return result\nend\n\nitemObject.onItemUse = function(target, user)\n    target:addStatusEffect(xi.effect.TELEPORT, { power = xi.teleport.id.PURGONORGO, duration = 3, origin = user, icon = 0 })\nend\n\nreturn itemObject\n"},["scripts/items/magnus_stone_pouch.lua"]={["Path"]="scripts/items/magnus_stone_pouch.lua",["SHA256"]="49e006f490b9b5d09f91b864568284c4ee5d0f1b9cb0963f9e098962b3e2b5f0",["Text"]="-----------------------------------\n-- ID: 5443\n-- magnus_stone_pouch\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.MAGNUS_STONE, 99 } })\nend\n\nreturn itemObject\n"},["scripts/items/maharajas_belt.lua"]={["Path"]="scripts/items/maharajas_belt.lua",["SHA256"]="c3c3ea7a1abeccf9879225fc7dc59cc0e132417d27178ab33b5663c48674c184",["Text"]="-----------------------------------\n-- ID: 15870\n-- Item: maharajas_belt\n-- Item Effect: AGI +10\n-- Duration: 60 seconds\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if target:getStatusEffectBySource(xi.effect.ENCHANTMENT, xi.effectSourceType.EQUIPPED_ITEM, xi.item.MAHARAJAS_BELT) ~= nil then\n        target:delStatusEffect(xi.effect.ENCHANTMENT, nil, xi.effectSourceType.EQUIPPED_ITEM, xi.item.MAHARAJAS_BELT)\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    if target:hasEquipped(xi.item.MAHARAJAS_BELT) then\n        target:addStatusEffect(xi.effect.ENCHANTMENT, { duration = 60, origin = user, sourceType = xi.effectSourceType.EQUIPPED_ITEM, sourceTypeParam = xi.item.MAHARAJAS_BELT })\n    end\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.AGI, 10)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/mahogany_bed.lua"]={["Path"]="scripts/items/mahogany_bed.lua",["SHA256"]="3d4d8838918580b0a0647335d42b309be7ee4d6f84db338717a88599f8becff8",["Text"]="-----------------------------------\n-- ID: 4\n-- Item: Mahogany Bed\n-----------------------------------\n---@type TItemFurniture\nlocal itemObject = {}\n\nitemObject.onFurniturePlaced = function(player)\n    if player:getQuestStatus(xi.questLog.OTHER_AREAS, xi.quest.id.otherAreas.THE_MOOGLE_PICNIC) == xi.questStatus.QUEST_AVAILABLE then\n        xi.quest.setVar(player, xi.questLog.OTHER_AREAS, xi.quest.id.otherAreas.THE_MOOGLE_PICNIC, 'bedPlacedTime', GetSystemTime())\n        xi.quest.setLocalVar(player, xi.questLog.OTHER_AREAS, xi.quest.id.otherAreas.THE_MOOGLE_PICNIC, 'mustZone', 1)\n    end\nend\n\nitemObject.onFurnitureRemoved = function(player)\n    xi.quest.setVar(player, xi.questLog.OTHER_AREAS, xi.quest.id.otherAreas.THE_MOOGLE_PICNIC, 'bedPlacedTime', 0)\nend\n\nreturn itemObject\n"},["scripts/items/mammut.lua"]={["Path"]="scripts/items/mammut.lua",["SHA256"]="6ed625a5fe73b1ca6b286697549610e140f68b22d737df5d5b2ab0258dff9399",["Text"]="-----------------------------------\n-- ID: 18503\n-- Item: Mammut\n-- Additional effect: ice damage\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\n-- Made up stats, taken from old sql.\nitemObject.onItemAdditionalEffect = function(actor, target, baseAttackDamage, item)\n    local pTable =\n    {\n        chance         = 10,\n        basePower      = 15,\n        attackType     = xi.attackType.MAGICAL,\n        magicalElement = xi.element.ICE,\n        canMAB         = false,\n        canResist      = true,\n    }\n\n    return xi.combat.action.executeAddEffectDamage(actor, target, pTable)\nend\n\nreturn itemObject\n"},["scripts/items/mamool_ja_earring.lua"]={["Path"]="scripts/items/mamool_ja_earring.lua",["SHA256"]="b86051b17e2cb53216774f39b2639b28aab610f26aa4ba17c398bd2613a6a52e",["Text"]="-----------------------------------\n-- ID: 16012\n-- Mamool Ja Earring\n--  This earring functions in the same way as the spell Reraise III.\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    local duration = 3600\n    target:delStatusEffect(xi.effect.RERAISE)\n    target:addStatusEffect(xi.effect.RERAISE, { power = 3, duration = duration, origin = user })\nend\n\nreturn itemObject\n"},["scripts/items/mamoolbane.lua"]={["Path"]="scripts/items/mamoolbane.lua",["SHA256"]="64807e17e437f09172bed34fd0014f6a757f8c8e534467db5fa96bf670d5b185",["Text"]="-----------------------------------\n-- ID: 18692\n-- Item: Mamoolbane\n-- Item Effect: Enchantment: Evasion +10\n-- Duration: 60 Minutes\n-- Only usable in Arrapago Reef, Halvung, or Mamook. Effect lost upon zoning or unequipping.\n-- https://wiki.ffo.jp/html/4401.html\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    local zoneId = target:getZoneID()\n\n    if\n        zoneId == xi.zone.ARRAPAGO_REEF or\n        zoneId == xi.zone.HALVUNG or\n        zoneId == xi.zone.MAMOOK\n    then\n        return 0\n    else\n        return xi.msg.basic.CANT_BE_USED_IN_AREA\n    end\nend\n\nitemObject.onItemUse = function(target, user)\n    if target:hasEquipped(xi.item.MAMOOLBANE) then\n        target:addStatusEffect(xi.effect.ENCHANTMENT, { duration = 3600, origin = user, flag = xi.effectFlag.ON_ZONE, sourceType = xi.effectSourceType.EQUIPPED_ITEM, sourceTypeParam = xi.item.MAMOOLBANE })\n    end\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.EVA, 10)\nend\n\nitemObject.onItemUnequip = function(target, item)\n    target:delStatusEffect(xi.effect.ENCHANTMENT, nil, xi.effectSourceType.EQUIPPED_ITEM, xi.item.MAMOOLBANE)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/mana_cloak.lua"]={["Path"]="scripts/items/mana_cloak.lua",["SHA256"]="4380f1ad289329ffc05f361214f6dcce04f9ec203cc70b5b140747535e1e6260",["Text"]="-----------------------------------\n-- ID: 14491\n-- Item: Mana Cloak\n-- Item Effect: Restores 20-35 MP\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if target:getMP() == target:getMaxMP() then\n        return xi.msg.basic.ITEM_UNABLE_TO_USE\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target)\n    local mpHeal = math.randomInt(20, 35)\n    local dif = target:getMaxMP() - target:getMP()\n    if mpHeal > dif then\n        mpHeal = dif\n    end\n\n    target:addMP(mpHeal)\n    target:messageBasic(xi.msg.basic.RECOVERS_MP, 0, mpHeal)\nend\n\nreturn itemObject\n"},["scripts/items/mana_tunic.lua"]={["Path"]="scripts/items/mana_tunic.lua",["SHA256"]="adde73a7a49832d090cd5aeff89e5f644f4f30f7381fa269e5b44c05b13dc864",["Text"]="-----------------------------------\n-- ID: 14490\n-- mana_tunic\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if target:getMP() == target:getMaxMP() then\n        return xi.msg.basic.ITEM_UNABLE_TO_USE\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target)\n    local mpHeal = math.randomInt(30, 40)\n    local dif = target:getMaxMP() - target:getMP()\n    if mpHeal > dif then\n        mpHeal = dif\n    end\n\n    target:addMP(mpHeal)\n    target:messageBasic(xi.msg.basic.RECOVERS_MP, 0, mpHeal)\nend\n\nreturn itemObject\n"},["scripts/items/mana_wand.lua"]={["Path"]="scripts/items/mana_wand.lua",["SHA256"]="d8c836250869f21de4b31c9ccdefdb446bb0ad0e74b269486f659ce5eda62fb1",["Text"]="-----------------------------------\n-- ID: 18402\n-- Item: mana_wand\n-- Item Effect: MPHEAL +2\n-- Duration: 30 seconds\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if target:getStatusEffectBySource(xi.effect.ENCHANTMENT, xi.effectSourceType.EQUIPPED_ITEM, xi.item.MANA_WAND) ~= nil then\n        target:delStatusEffect(xi.effect.ENCHANTMENT, nil, xi.effectSourceType.EQUIPPED_ITEM, xi.item.MANA_WAND)\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    if target:hasEquipped(xi.item.MANA_WAND) then\n        target:addStatusEffect(xi.effect.ENCHANTMENT, { duration = 1800, origin = user, sourceType = xi.effectSourceType.EQUIPPED_ITEM, sourceTypeParam = xi.item.MANA_WAND })\n    end\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.MPHEAL, 2)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/manashell_ring.lua"]={["Path"]="scripts/items/manashell_ring.lua",["SHA256"]="f2f2ff734504c7915896c9cef794b485a7f7239240ea295a8a9a38a62a07c263",["Text"]="-----------------------------------\n-- ID: 15782\n-- Item: Manashell Ring\n-- Item Effect: MP +9\n-- Duration: 3 minutes\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, user)\n    if target:getStatusEffectBySource(xi.effect.MAX_MP_BOOST, xi.effectSourceType.EQUIPPED_ITEM, xi.item.MANASHELL_RING) ~= nil then\n        target:delStatusEffect(xi.effect.MAX_MP_BOOST, nil, xi.effectSourceType.EQUIPPED_ITEM, xi.item.MANASHELL_RING)\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    if target:hasEquipped(xi.item.MANASHELL_RING) then\n        target:addStatusEffect(xi.effect.MAX_MP_BOOST, { duration = 180, origin = user, sourceType = xi.effectSourceType.EQUIPPED_ITEM, sourceTypeParam = xi.item.MANASHELL_RING })\n    end\nend\n\nitemObject.onEffectGain = function(target, effect)\n    effect:addMod(xi.mod.MP, 9)\nend\n\nitemObject.onEffectLose = function(target, effect)\nend\n\nreturn itemObject\n"},["scripts/items/mandragora_belt.lua"]={["Path"]="scripts/items/mandragora_belt.lua",["SHA256"]="e6d711f1158ff7e62af20591e82a781ecdb6556fb6c84c90a54db25c51071dfc",["Text"]="-----------------------------------\n-- ID: 15299\n-- Mandragora Belt\n-- Enchantment: 60Min, Costume - Mandragora\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if not target:canUseMisc(xi.zoneMisc.COSTUME) then\n        return xi.msg.basic.CANT_BE_USED_IN_AREA\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    target:addStatusEffect(xi.effect.COSTUME, { power = 31, duration = 3600, origin = user })\nend\n\nreturn itemObject\n"},["scripts/items/mandragora_beret.lua"]={["Path"]="scripts/items/mandragora_beret.lua",["SHA256"]="7797eef5c808b88093a63dad5b8d47f7899f6eb0964b771cc39c61d271570a3f",["Text"]="-----------------------------------\n-- ID: 15204\n-- Mandragora Beret\n-- Enchantment: 60Min, Costume - Mandragora (white)\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if not target:canUseMisc(xi.zoneMisc.COSTUME) then\n        return xi.msg.basic.CANT_BE_USED_IN_AREA\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    target:addStatusEffect(xi.effect.COSTUME, { power = 31, duration = 3600, origin = user })\nend\n\nreturn itemObject\n"},["scripts/items/manji_shuriken_pouch.lua"]={["Path"]="scripts/items/manji_shuriken_pouch.lua",["SHA256"]="0c148394b0a28db8a1099082af871eaac5d5bd961034012b2197a75368228754",["Text"]="-----------------------------------\n-- ID: 6298\n-- Item: Manji Shr. Pouch\n-- When used, you will obtain one stack of Manji Shurikens\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.MANJI_SHURIKEN, 99 } })\nend\n\nreturn itemObject\n"},["scripts/items/mantid_quiver.lua"]={["Path"]="scripts/items/mantid_quiver.lua",["SHA256"]="4013ba71fd6fecd632ccd0ab5bb304003bfa4d05985de859fa95bb8efe4ca3ee",["Text"]="-----------------------------------\n-- ID: 6138\n-- Mantid Quiver\n-- When used, you will obtain one stack of Mantid Arrows\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    return xi.itemUtils.itemBoxOnItemCheck(target)\nend\n\nitemObject.onItemUse = function(target)\n    npcUtil.giveItem(target, { { xi.item.MANTID_ARROW, 99 } })\nend\n\nreturn itemObject\n"},["scripts/items/maple_cake.lua"]={["Path"]="scripts/items/maple_cake.lua",["SHA256"]="e493f5ba1f671c364ea00d6b6ac6f4738644b4e6a1fbc2df510ea5d3ae5e5198",["Text"]="-----------------------------------\n-- ID: 5625\n-- Item: Maple Cake\n-- Food Effect: 3 Hrs, All Races\n-----------------------------------\n-- TODO: Group Effect\n-- HP Recoverd while healing 1\n-- MP Recovered while healing 4\n-----------------------------------\n---@type TItem