OWER))\n    target:addStatusEffect(xi.effect.MEDICINE, { duration = 900, origin = user })\nend\n\nreturn itemObject\n"},["scripts/items/max-potion_+1.lua"]={["Path"]="scripts/items/max-potion_+1.lua",["SHA256"]="5568768581604095b96f2eaec677be1565bf6392355413a44f78fc30e9f7a98e",["Text"]="-----------------------------------\n-- ID: 4125\n-- Item: Max-Potion +1\n-- Item Effect: Restores 550 HP\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if target:getHP() == target:getMaxHP() then\n        return xi.msg.basic.ITEM_UNABLE_TO_USE\n    elseif target:hasStatusEffect(xi.effect.MEDICINE) then\n        return xi.msg.basic.ITEM_NO_USE_MEDICATED\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    target:messageBasic(xi.msg.basic.RECOVERS_HP, 0, target:addHP(550 * xi.settings.main.ITEM_POWER))\n    target:addStatusEffect(xi.effect.MEDICINE, { duration = 900, origin = user })\nend\n\nreturn itemObject\n"},["scripts/items/max-potion_+2.lua"]={["Path"]="scripts/items/max-potion_+2.lua",["SHA256"]="3f269708760f70cee1db264dc03cb1558119e2f7b07c280007f0b6f0fb05d30e",["Text"]="-----------------------------------\n-- ID: 4126\n-- Item: Max-Potion +2\n-- Item Effect: Restores 650 HP\n-----------------------------------\n---@type TItem\nlocal itemObject = {}\n\nitemObject.onItemCheck = function(target, item, caster)\n    if target:getHP() == target:getMaxHP() then\n        return xi.msg.basic.ITEM_UNABLE_TO_USE\n    elseif target:hasStatusEffect(xi.effect.MEDICINE) then\n        return xi.msg.basic.ITEM_NO_USE_MEDICATED\n    end\n\n    return 0\nend\n\nitemObject.onItemUse = function(target, user)\n    target:messageBasic(xi.msg.basic.RECOVERS_HP, 0, target:addHP(650 * xi.settings.main.ITEM_POWER))\n    target:addStatusEffect(xi.effect.MEDICINE, { duration = 900, origin = user })\nend\n\nreturn itemObject\n"},["scripts/items/max-potion_+3.lua"]={["Path"]="scripts/i